mapper.select:

SELECT
    /* 이번 달 총 청구 금액 */
    IFNULL(SUM(IF(
            i.invoiceStatus <> 'canceled'
                AND i.invoiceDt >= d.s AND i.invoiceDt < d.e,
            i.totalAmt, 0
               )), 0) AS monthInvoiceTotal,

    /* 입금 완료율(%) */
    IFNULL(
            FLOOR(
                    100 * SUM(IF(
                            i.invoiceStatus = 'paid'
                                AND i.invoiceDt >= d.s AND i.invoiceDt < d.e, 1, 0
                              )) / NULLIF(SUM(IF(
                            i.invoiceStatus <> 'canceled'
                                AND i.invoiceDt >= d.s AND i.invoiceDt < d.e, 1, 0
                                              )), 0)
            ), 0
    )                 AS paidRatePct,

    /* 발행 중 건수 */
    SUM(IF(
            i.invoiceStatus IN ('issued')
                AND i.invoiceDt >= d.s AND i.invoiceDt < d.e, 1, 0
        ))            AS issuingCount,

    /* 미발행 건수 */
    SUM(IF(
            i.invoiceStatus IN ('draft')
                AND i.invoiceDt >= d.s AND i.invoiceDt < d.e, 1, 0
        ))            AS unpaidCount

FROM invoice i
         JOIN (SELECT DATE_SUB(CURDATE(), INTERVAL DAY(CURDATE()) - 1 DAY) AS s, /* 이번 달 1일 00:00:00 */
                      DATE_ADD(LAST_DAY(CURDATE()), INTERVAL 1 DAY)        AS e /* 다음 달 1일 00:00:00 */
) d


SELECT
    /* 이번 달 매출 합계 */
    IFNULL(SUM(IF(r.revenueDt >= d.s AND r.revenueDt < d.e, r.totalAmt, 0)), 0)   AS monthRevenueTotal,
    /* 전월 매출 합계 */
    IFNULL(SUM(IF(r.revenueDt >= d.ps AND r.revenueDt < d.pe, r.totalAmt, 0)), 0) AS prevMonthTotal,
    /* 이번 달 매출 건수 */
    COUNT(IF(r.revenueDt >= d.s AND r.revenueDt < d.e, 1, NULL))                  AS revenueCount
FROM revenue r
         JOIN (
    /* 이번 달 [s,e), 전월 [ps,pe) */
    SELECT DATE_SUB(CURDATE(), INTERVAL DAY(CURDATE()) - 1 DAY)                             AS s, /* 이번 달 1일 00:00:00 */
           DATE_ADD(LAST_DAY(CURDATE()), INTERVAL 1 DAY)                                    AS e, /* 다음 달 1일 00:00:00 */
           DATE_SUB(DATE_SUB(CURDATE(), INTERVAL DAY(CURDATE()) - 1 DAY), INTERVAL 1 MONTH) AS ps, /* 전월 1일 */
           DATE_SUB(DATE_SUB(CURDATE(), INTERVAL DAY(CURDATE()) - 1 DAY), INTERVAL 0 DAY)   AS pe /* 이번 달 1일 */
) d
